import{_ as r,K as i,a as n,c as s,ac as e,q as d}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"数据结构导论（02142） · 基本概念与复杂度至树与二叉树","description":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","frontmatter":{"title":"数据结构导论（02142） · 基本概念与复杂度至树与二叉树","description":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","splitFrom":"principles/data-structures/foundations/datastructure.md","showdocs":{"topics":[{"id":"data-structures","title":"数据结构","link":"/topics/data-structures/"}],"kind":"专题笔记","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"数据结构导论（02142）","summary":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","status":"active","related":[{"title":"数据结构导论（02142）","link":"/principles/data-structures/foundations/datastructure","kind":"专题笔记","scope":"general","audience":"general"},{"title":"数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收","link":"/principles/data-structures/foundations/datastructure-part-02","kind":"专题笔记","scope":"general","audience":"general"},{"title":"并查集","link":"/principles/data-structures/trees/union-find","kind":"系统学习","scope":"general","audience":"general"},{"title":"层序遍历","link":"/principles/data-structures/trees/tree-level-order","kind":"系统学习","scope":"general","audience":"general"},{"title":"差分数组","link":"/principles/data-structures/structures/difference-array","kind":"系统学习","scope":"general","audience":"general"}],"prev":{"text":"数据结构导论（02142）","link":"/principles/data-structures/foundations/datastructure"},"next":{"text":"数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收","link":"/principles/data-structures/foundations/datastructure-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数据结构导论（02142）","link":"/principles/data-structures/foundations/datastructure"},"next":{"text":"数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收","link":"/principles/data-structures/foundations/datastructure-part-02"}},"headers":[],"relativePath":"principles/data-structures/foundations/datastructure-part-01.md","filePath":"principles/data-structures/foundations/datastructure-part-01.md"}'),o={name:"principles/data-structures/foundations/datastructure-part-01.md"};function p(c,a,l,u,h,_){const t=i("Mermaid");return n(),s("div",null,[a[0]||(a[0]=e(`<h1 id="数据结构导论-02142-·-基本概念与复杂度至树与二叉树" tabindex="-1">数据结构导论（02142） · 基本概念与复杂度至树与二叉树 <a class="header-anchor" href="#数据结构导论-02142-·-基本概念与复杂度至树与二叉树" aria-label="Permalink to &quot;数据结构导论（02142） · 基本概念与复杂度至树与二叉树&quot;">​</a></h1><p><a href="/principles/data-structures/foundations/datastructure">返回分篇目录</a></p><p>学习顺序是：先分清逻辑结构与存储方式，再学习线性表、栈队列、树和图，最后比较查找与排序。每一类结构都按“表示 → 操作 → 复杂度 → 选择条件”理解，算法实现可继续读对应手册。</p><h2 id="数据结构导论-02142" tabindex="-1">数据结构导论（02142） <a class="header-anchor" href="#数据结构导论-02142" aria-label="Permalink to &quot;数据结构导论（02142） {#数据结构导论-02142}&quot;">​</a></h2><p>学习顺序是：先分清逻辑结构与存储方式，再学习线性表、栈队列、树和图，最后比较查找与排序。每一类结构都按“表示 → 操作 → 复杂度 → 选择条件”理解，算法实现可继续读对应手册。</p><p><span id="第一章-概论-重点" aria-hidden="true"></span><span id="_1-引言" aria-hidden="true"></span><span id="_2-基本概念和术语" aria-hidden="true"></span><span id="算法及描述" aria-hidden="true"></span><span id="_4-算法分析" aria-hidden="true"></span><span id="_5-小结" aria-hidden="true"></span></p><h2 id="basics" tabindex="-1">基本概念与复杂度 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;基本概念与复杂度 {#basics}&quot;">​</a></h2><h3 id="数据、结构与操作" tabindex="-1">数据、结构与操作 <a class="header-anchor" href="#数据、结构与操作" aria-label="Permalink to &quot;数据、结构与操作 {#数据、结构与操作}&quot;">​</a></h3><p>数据元素是处理的基本单位，数据项是元素中有意义的组成部分。逻辑结构描述元素之间的关系：集合、线性、树形、图；存储结构描述这些关系如何落在内存中：顺序、链式、索引、散列。</p><p>同一逻辑结构可以有不同存储实现，例如线性表可用数组或链表。读取、查找属于不改变结构的引用操作；插入、删除会改变结构，修改元素值也不是纯读取。不能因为它们都属于“基本运算”就归成同一类。</p><p>算法用明确、可执行且有限的步骤求解问题，允许零个或多个输入，产生输出。正确性、可读性、健壮性和效率是不同检查维度。</p><h3 id="分析时间与辅助空间" tabindex="-1">分析时间与辅助空间 <a class="header-anchor" href="#分析时间与辅助空间" aria-label="Permalink to &quot;分析时间与辅助空间 {#分析时间与辅助空间}&quot;">​</a></h3><p>常见增长量级为 <code>O(1)</code>、<code>O(log n)</code>、<code>O(n)</code>、<code>O(n log n)</code>、<code>O(n²)</code>、<code>O(2^n)</code>。复杂度取决于实际执行次数，不是简单数循环层数：折半循环是对数级，嵌套循环也可能具有相互受限的范围。</p><p>辅助空间关注为算法额外申请的变量、容器和递归栈，与输入本身占用空间区分。分析时说明平均、最好还是最坏情况，不能把平均界写成所有输入的保证。</p><p><span id="第二章-线性表-重点" aria-hidden="true"></span><span id="_1-线性表的基本概念" aria-hidden="true"></span><span id="_2-线性表的顺序存储" aria-hidden="true"></span><span id="_3-线性表的链接存储" aria-hidden="true"></span><span id="_4、5-其它运算在单链表的实现、其他链表" aria-hidden="true"></span><span id="_6-顺序实现与链式实现的比较" aria-hidden="true"></span><span id="_7-小结" aria-hidden="true"></span></p><h2 id="linear-lists" tabindex="-1">线性表：顺序存储与链式存储 <a class="header-anchor" href="#linear-lists" aria-label="Permalink to &quot;线性表：顺序存储与链式存储 {#linear-lists}&quot;">​</a></h2><h3 id="顺序表的读取、插入与删除" tabindex="-1">顺序表的读取、插入与删除 <a class="header-anchor" href="#顺序表的读取、插入与删除" aria-label="Permalink to &quot;顺序表的读取、插入与删除 {#顺序表的读取、插入与删除}&quot;">​</a></h3><p>线性表是有限序列，除两端外每个元素有唯一直接前驱和后继。顺序表用连续存储单元表示，支持按下标访问；元素大小 L、首地址 d，按一基位置编号时：<code>LOC(aᵢ) = d + (i−1)L</code>。</p><p>长度为 n 的表，在第 i 个位置插入需要后移 <code>n−i+1</code> 个元素；删除第 i 个元素后需要前移 <code>n−i</code> 个元素。末尾追加/删除无需移动其他元素，但追加仍可能触发扩容。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始：[10, 20, 30]</span></span>
<span class="line"><span>第2个位置插入15：先后移30、20，再写入15 → [10, 15, 20, 30]</span></span>
<span class="line"><span>删除第2个元素：前移20、30，再减少长度 → [10, 20, 30]</span></span></code></pre></div><p>移动元素前先校验位置和容量，不能在移动过程中覆盖尚未保存的元素。</p><h3 id="单链表与双向链表" tabindex="-1">单链表与双向链表 <a class="header-anchor" href="#单链表与双向链表" aria-label="Permalink to &quot;单链表与双向链表 {#单链表与双向链表}&quot;">​</a></h3><p>图中q被插入p与r之间。必须先让q保留原后继r，再改p的连接；如果是双向链表，还要同步更新反向指针。</p>`,23)),d(t,{source:"Zmxvd2NoYXJ0IExSCiBQWyLlt7LmnInoioLngrlwIl0gLS0+IFFbIuaWsOiKgueCuXEiXQogUSAtLT4gUlsi5Y6f5ZCO57unciJdCiBQIC0uICLooqvmm7/mjaLnmoTljp/ov57mjqUiIC4tPiBSCg=="}),a[1]||(a[1]=e(`<p>链表节点用数据域与指针表达逻辑相邻关系，物理位置可以不连续。单链表保存后继，双向链表另存前驱；循环链表的尾部连接回头节点或首节点，具体形式必须与实现约定一致。</p><p>已知前驱 p，插入节点 q 的关键顺序是先保存后继，再改 p 的连接：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>q.next = p.next</span></span>
<span class="line"><span>p.next = q</span></span></code></pre></div><p>删除 p 的后继时，先保存被删节点，再连接并释放；同时处理头、尾、空表及单节点边界。双向链表还需同步修改另一方向的连接，不能只改 <code>next</code>。</p><h3 id="如何选择与比较复杂度" tabindex="-1">如何选择与比较复杂度 <a class="header-anchor" href="#如何选择与比较复杂度" aria-label="Permalink to &quot;如何选择与比较复杂度 {#如何选择与比较复杂度}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作或条件</th><th>顺序表</th><th>单链表</th></tr></thead><tbody><tr><td>按位置读取</td><td><code>O(1)</code></td><td><code>O(n)</code></td></tr><tr><td>未建立额外索引的按值查找</td><td><code>O(n)</code></td><td><code>O(n)</code></td></tr><tr><td>已知位置插入/删除</td><td>通常移动 <code>O(n)</code> 个元素</td><td>已知前驱时连接修改 <code>O(1)</code>；找前驱仍可能 <code>O(n)</code></td></tr><tr><td>空间</td><td>数据连续，可能预留容量</td><td>节点分散，需要指针与分配开销</td></tr></tbody></table><p>顺序表不只限于静态分配，也可动态扩容；链表也并非“有空闲内存就一定分配成功”。存储密度是数据域占用与整个节点占用之比，比较时还要考虑容量浪费、对齐和缓存局部性。</p><p><span id="第三章-栈、队列和数组-重点" aria-hidden="true"></span><span id="_1-栈" aria-hidden="true"></span><span id="_2-队列-queue" aria-hidden="true"></span><span id="_3-数组、应用" aria-hidden="true"></span><span id="_4-小结" aria-hidden="true"></span></p><h2 id="stack-queue-array" tabindex="-1">栈、队列与数组 <a class="header-anchor" href="#stack-queue-array" aria-label="Permalink to &quot;栈、队列与数组 {#stack-queue-array}&quot;">​</a></h2><h3 id="栈-后进先出" tabindex="-1">栈：后进先出 <a class="header-anchor" href="#栈-后进先出" aria-label="Permalink to &quot;栈：后进先出 {#栈-后进先出}&quot;">​</a></h3><p>栈只在栈顶插入和删除，<code>push</code> 入栈、<code>pop</code> 出栈，规则为 <strong>后进先出（LIFO）</strong>。递归调用、括号匹配、撤销等场景会使用栈式顺序。顺序栈要检查容量，链栈要检查空栈与分配失败。</p><p>原笔记把 LIFO 写成“先进先出”是混淆；按 <code>A、B、C</code> 入栈，未穿插其他操作时弹出次序应为 <code>C、B、A</code>。</p><h3 id="队列与循环队列" tabindex="-1">队列与循环队列 <a class="header-anchor" href="#队列与循环队列" aria-label="Permalink to &quot;队列与循环队列 {#队列与循环队列}&quot;">​</a></h3><p>容量4、保留一个空槽的队列最多装3项。下图只画数组槽位的回绕关系，当前是否为空或满还要结合front、rear判断。</p>`,14)),d(t,{source:"Zmxvd2NoYXJ0IExSCiBBWyLmp70wIl0gLS0+IEJbIuanvTEiXQogQiAtLT4gQ1si5qe9MiJdCiBDIC0tPiBEWyLmp70zIl0KIEQgLS0+fCLmqKE05Zue57uVInwgQQo="}),a[2]||(a[2]=e('<p>队列从队尾插入、队头删除，为 <strong>先进先出（FIFO）</strong>。<code>A、B、C</code> 依次入队，出队仍为 <code>A、B、C</code>。顺序队列若只递增下标，会出现前端空间不能复用的“假溢出”。</p><p>循环队列用取模回绕。若数组容量为 m、约定空出一个位置、front 指向队头、rear 指向下次写入处：</p><ul><li>空：<code>front == rear</code>。</li><li>满：<code>(rear + 1) % m == front</code>。</li><li>入队后：<code>rear = (rear + 1) % m</code>。</li><li>出队后：<code>front = (front + 1) % m</code>。</li></ul><p>这种实现最多存 <code>m−1</code> 个元素；如果采用计数器或满标记，满空公式会不同。链队列要同步维护头尾指针，尤其最后一个元素出队时。</p><h3 id="多维数组与矩阵压缩" tabindex="-1">多维数组与矩阵压缩 <a class="header-anchor" href="#多维数组与矩阵压缩" aria-label="Permalink to &quot;多维数组与矩阵压缩 {#多维数组与矩阵压缩}&quot;">​</a></h3><p>数组按索引访问；二维数组采用行优先、零基下标、每元素 k 字节时，<code>LOC(a[i][j]) = base + (i × 列数 + j) × k</code>。更换下界或存储顺序后需调整公式。</p><p>对称、三角矩阵可利用结构少存重复元素；稀疏矩阵按行列位置保存非零项。压缩不是“所有非零只分配一个空间”，而是用索引或规则重建未显式保存的项，访问成本也会变化。</p><p><span id="第四章树和二叉树-重、难点" aria-hidden="true"></span><span id="_1-树的基本概念" aria-hidden="true"></span><span id="_2-二叉树" aria-hidden="true"></span><span id="_3-二叉树的存储结构" aria-hidden="true"></span><span id="_4-二叉树的遍历" aria-hidden="true"></span><span id="_5-树和森林" aria-hidden="true"></span><span id="_6-判定树和哈夫曼树" aria-hidden="true"></span><span id="_7-小结-1" aria-hidden="true"></span></p><h2 id="trees" tabindex="-1">树与二叉树 <a class="header-anchor" href="#trees" aria-label="Permalink to &quot;树与二叉树 {#trees}&quot;">​</a></h2><h3 id="术语、性质与存储" tabindex="-1">术语、性质与存储 <a class="header-anchor" href="#术语、性质与存储" aria-label="Permalink to &quot;术语、性质与存储 {#术语、性质与存储}&quot;">​</a></h3><p>树是递归结构，根以外的节点有唯一父节点；叶子没有孩子，节点的度是孩子数，树的度是最大节点度。约定根为第 1 层时，高度是最大层数。</p><p>二叉树区分左右子树，每个节点至多两个孩子；不要求每个节点都有两个孩子。常用性质：</p><ul><li>第 i 层最多 <code>2^(i−1)</code> 个节点。</li><li>高度 k 最多 <code>2^k−1</code> 个节点。</li><li>非空二叉树的叶子数 <code>n₀ = n₂ + 1</code>，n₂ 为有两个孩子的节点数。</li><li>满二叉树每层填满；完全二叉树除最后一层外填满，最后一层从左连续排列。</li></ul><p>数组存储适合完全二叉树等布局，一基编号时节点 i 的孩子为 <code>2i</code>、<code>2i+1</code>；倾斜树可能浪费大量数组位置。链式结构保存左右孩子指针，操作时仍需维护正确关系。</p><h3 id="先序、中序、后序与层序遍历" tabindex="-1">先序、中序、后序与层序遍历 <a class="header-anchor" href="#先序、中序、后序与层序遍历" aria-label="Permalink to &quot;先序、中序、后序与层序遍历 {#先序、中序、后序与层序遍历}&quot;">​</a></h3>',15)),d(t,{source:"Z3JhcGggVEQKICBBKChBKSkgLS0+IEIoKEIpKQogIEEgLS0+IEMoKEMpKQogIEIgLS0+IEQoKEQpKQogIEIgLS0+IEUoKEUpKQogIEMgLS0+IEYoKEYpKQogIEMgLS0+IEcoKEcpKQo="}),a[3]||(a[3]=e('<table tabindex="0"><thead><tr><th>遍历</th><th>规则</th><th>此图结果</th></tr></thead><tbody><tr><td>先序</td><td>根、左、右</td><td><code>A B D E C F G</code></td></tr><tr><td>中序</td><td>左、根、右</td><td><code>D B E A F C G</code></td></tr><tr><td>后序</td><td>左、右、根</td><td><code>D E B F G C A</code></td></tr><tr><td>层序</td><td>按层从左到右</td><td><code>A B C D E F G</code></td></tr></tbody></table><p>深度遍历可用递归或显式栈，层序常用队列。每个节点访问一次通常为 <code>O(n)</code>；递归辅助空间取决于高度，不能一律写 <code>O(log n)</code>。</p><p>实现对照见 <a href="/principles/data-structures/trees/algorithms-trees-general-general#scene-visit-tree">树的四种遍历</a>。</p><h3 id="一般树、森林与哈夫曼树" tabindex="-1">一般树、森林与哈夫曼树 <a class="header-anchor" href="#一般树、森林与哈夫曼树" aria-label="Permalink to &quot;一般树、森林与哈夫曼树 {#一般树、森林与哈夫曼树}&quot;">​</a></h3><p>权值1、2、4先合并最小的1与2得到3，再合并3与4得到7。叶子权值乘深度的总和为1×2+2×2+4×1=10；每次选择的是当前森林最小两棵，合并节点也要重新参与选择。</p>',5)),d(t,{source:"Zmxvd2NoYXJ0IFRECiBSWyLmoLk3Il0gLS0+IFhbIuWGhemDqOiKgueCuTMiXQogUiAtLT4gQ1si5Y+2NCJdCiBYIC0tPiBBWyLlj7YxIl0KIFggLS0+IEJbIuWPtjIiXQo="}),a[4]||(a[4]=e('<p>一般树可用双亲数组、孩子链表或孩子—兄弟结构表示。孩子—兄弟表示中，左指针对应第一个孩子，右指针对应下一个兄弟；森林可把各树根视作兄弟连接。理解指针含义比记“旋转 45 度”更可靠。</p><p>一般树有先根、后根和层序遍历；不能未经定义就把二叉树中序直接移植为一般树中序。</p><p>哈夫曼树用于使带权路径长度最小：从权值森林中反复选最小两棵，合并为权值之和的新树，直到只剩一棵。按边赋予 0/1 得到前缀编码；相同权值可能产生不同树与编码，但总带权路径长度相同。</p><p><span id="第五章-图-重点" aria-hidden="true"></span><span id="_1-图的基本概念" aria-hidden="true"></span><span id="_2-图的存储结构" aria-hidden="true"></span><span id="_3-图的遍历" aria-hidden="true"></span><span id="_4-图的应用" aria-hidden="true"></span><span id="_5-小结-1" aria-hidden="true"></span></p>',4))])}const m=r(o,[["render",p]]);export{b as __pageData,m as default};
